import{c as l,Q as e,j as d,m as t}from"./chunks/framework.DOi4mjdC.js";const D=JSON.parse('{"title":"内置变量","description":"","frontmatter":{},"headers":[{"level":1,"title":"内置变量","slug":"内置变量"}],"relativePath":"api/SIMT-API/SIMD与SIMT混合编程简介/扩展语法/内置变量-145.md","filePath":"api/SIMT-API/SIMD与SIMT混合编程简介/扩展语法/内置变量-145.md"}'),a={name:"api/SIMT-API/SIMD与SIMT混合编程简介/扩展语法/内置变量-145.md"};function r(p,i,o,c,x,m){return e(),d("div",null,[...i[0]||(i[0]=[t('<h1 id="内置变量" tabindex="-1">内置变量 <a class="header-anchor" href="#内置变量" aria-label="Permalink to &quot;内置变量&quot;">​</a></h1><p>当前提供了以下仅在Device上可用的dim3结构的内置变量：</p><ul><li><p>blockDim</p><p>内置全局变量，在核函数中可以直接使用，用于获取线程块中配置的线程的三维层次结构。blockDim.x，blockDim.y，blockDim.z分别表示线程块中三个维度的线程数，各个维度上线程数需满足blockDim.x * blockDim.y *blockDim.z &lt;= 2048。</p></li><li><p>gridDim</p><p>内置全局变量，只能在核函数中使用，表示整个计算任务在各个维度上分别由多少个线程块构成。gridDim.x &lt;= 65535；gridDim.y、gridDim.z必须为1。</p></li><li><p>blockIdx</p><p>内置全局变量，只能在核函数中使用，用于获取块索引。表示当前线程所在的线程块在整个网格中的位置坐标。blockIdx.x的范围是0到gridDim.x - 1，blockIdx.y和blockIdx.z目前只能返回0。</p></li><li><p>threadIdx</p><p>内置全局变量，在核函数中可以直接使用，用于获取当前线程在线程块内部的索引。threadIdx.x，threadIdx.y，threadIdx.z分别表示当前线程在3个维度的索引，threadIdx.x的范围为[0, blockDim.x)，threadIdx.y的范围为[0, blockDim.y)，threadIdx.z的范围为[0, blockDim.z)。线程块内线程的索引计算方式如下：</p><ul><li>对于一维线程块，线程块内线程的索引为threadIdx.x。</li><li>对于二维线程块，线程块内线程的索引为(threadIdx.x + threadIdx.y * blockDim.x)。</li><li>对于三维线程块，线程块内线程的索引为(threadIdx.x + threadIdx.y * blockDim.x + threadIdx.z * blockDim.x * blockDim.y)。</li></ul></li></ul><p>当前提供了以下仅在Device上可用的int类型的内置变量：</p><ul><li><p>warpSize</p><p>运行时变量，表示一个线程束（Warp）中的线程数量，当前为固定值32。</p></li></ul>',5)])])}const _=l(a,[["render",r]]);export{D as __pageData,_ as default};
